	ORG	$0100
ENV_TYPE EQU 1 
OS_TYPE EQU 0
LD HL,($0001)
LD (WBOOTBK),HL
; WORK ZERO CLEAR
XOR A
LD HL,__WORK__
LD DE,__WORK__+1
LD BC,__WORKEND__-__WORK__-1
LD (HL),A
LDIR
 CALL RUNTIME_INIT
LD HL,EEC0H   ; LSX-Dodgers 1.62c
LD (_CTCVEC),HL
LD IY,__IYWORK
CALL MAIN
JP 0

PSGW:
; function PSGW
	PUSH	IY
	LD	BC,$0004
	ADD	IY,BC
	LD	L,(IY+$6C)
	LD	H,(IY+$6D)
	PUSH	HL
	LD	HL,$1C00
	POP	DE
	LD	B,H
	LD	C,L
	EX	DE,HL
	OUT	(C),L
	LD	L,(IY+$6E)
	LD	H,(IY+$6F)
	PUSH	HL
	LD	HL,$1B00
	POP	DE
	LD	B,H
	LD	C,L
	EX	DE,HL
	OUT	(C),L
_PSGW_EXIT:
	POP	IY
	RET

TONE:
; function TONE
	PUSH	IY
	LD	BC,$0004
	ADD	IY,BC
	LD	HL,$0000
	PUSH	HL
	LD	L,(IY+$6C)
	LD	H,(IY+$6D)
	LD	DE,$00FF
	LD	A,H
	AND	D
	LD	H,A
	LD	A,L
	AND	E
	LD	L,A
	LD	(IY+$72),L
	LD	(IY+$73),H
	POP	HL
	LD	(IY+$70),L
	LD	(IY+$71),H
	CALL	PSGW
	LD	HL,$0001
	PUSH	HL
	LD	L,(IY+$6C)
	LD	H,(IY+$6D)
	LD	DE,$0008
	CALL	RSHIFTHLDE
	LD	(IY+$72),L
	LD	(IY+$73),H
	POP	HL
	LD	(IY+$70),L
	LD	(IY+$71),H
	CALL	PSGW
	LD	HL,$0008
	PUSH	HL
	LD	HL,$000C
	LD	(IY+$72),L
	LD	(IY+$73),H
	POP	HL
	LD	(IY+$70),L
	LD	(IY+$71),H
	CALL	PSGW
	LD	HL,$0001
	LD	(_V_TONE_I),HL
_L0:
	LD	HL,$0001
	CALL	VSYNC
_L1:
	LD	HL,(_V_TONE_I)
	INC	HL
	LD	(_V_TONE_I),HL
	LD	E,(IY+$6E)
	LD	D,(IY+$6F)
	EX	DE,HL
	OR	A
	SBC	HL,DE
	JP	NC,_L0
_L2:
	LD	HL,$0008
	PUSH	HL
	LD	HL,$0000
	LD	(IY+$72),L
	LD	(IY+$73),H
	POP	HL
	LD	(IY+$70),L
	LD	(IY+$71),H
	CALL	PSGW
_TONE_EXIT:
	POP	IY
	RET

VSYNC_PROC:
; function VSYNC_PROC
_VSYNC_PROC_EXIT:
	RET

MAIN:
; function MAIN
	LD	HL,$0007
	PUSH	HL
	LD	HL,$003E
	LD	(IY+$72),L
	LD	(IY+$73),H
	POP	HL
	LD	(IY+$70),L
	LD	(IY+$71),H
	CALL	PSGW
	LD	HL,$0000
	LD	(_V_MAIN_I),HL
_L3:
	LD	HL,(_V_MAIN_I)
	ADD	HL,HL
	LD	DE,_V_MELODY
	ADD	HL,DE
	LD	E,(HL)
	INC	HL
	LD	D,(HL)
	EX	DE,HL
	LD	DE,$0000
	OR	A
	SBC	HL,DE
	JP	Z,_L4
	LD	HL,(_V_MAIN_I)
	ADD	HL,HL
	LD	DE,_V_MELODY
	ADD	HL,DE
	LD	E,(HL)
	INC	HL
	LD	D,(HL)
	EX	DE,HL
	PUSH	HL
	LD	HL,$000A
	LD	(IY+$72),L
	LD	(IY+$73),H
	POP	HL
	LD	(IY+$70),L
	LD	(IY+$71),H
	CALL	TONE
	LD	HL,(_V_MAIN_I)
	INC	HL
	LD	(_V_MAIN_I),HL
	JP	_L3
_L4:
	CALL	BEEP
_MAIN_EXIT:
	RET

_V_MELODY:
	DB	$DE,$AA,$7B,$66,$3F,$1C,$FD,$EF,$00

RUNTIME_INIT:
	RET

; === Runtime Functions ===
RSHIFTHLDE:
LD A, E
AND $0F
RET Z
.rshift1
SRL H
RR L
DEC A
JR NZ, .rshift1
RET

LSXCALLS:
BDOS EQU $0005
PRNOUT EQU $05
INPOUT EQU $06
DIRIO EQU $06
DIRIN	EQU	$07
GETS EQU $0A
CONST	EQU	$0B
lSCRN EQU $EFD0
lLOC EQU $EFD6
FCB1	EQU	005CH
FCB2	EQU	006CH
DTA1	EQU	0080H

sSYSTEM:
EXX
PUSH	BC
PUSH	DE
PUSH	HL
PUSH	IX
PUSH	IY
EXX
CALL	$0005
EXX
POP	IY
POP	IX
POP	HL
POP	DE
POP	BC
EXX
RET

sZPRINT:
EX	(SP),HL
.zprnt1
LD	A,(HL)
INC	HL
OR	A
JR	Z,.zprnt2
CALL	.zprnt3
JR	.zprnt1
.zprnt2
EX	(SP),HL
RET
.zprnt3
PUSH	BC
PUSH	DE
PUSH	HL
LD	E,A
LD	C,INPOUT
CALL sSYSTEM
POP	HL
POP	DE
POP	BC
RET

BEEP:
PUSH	AF
LD	A,7
JR	sPRNT01

sPRNT0:
PUSH	AF
CP	$20
JR	NC,sPRNT01
LD	A,$20
sPRNT01:
CALL	sPRINT
POP	AF
RET

sPRINT:
PUSH	BC
PUSH	DE
PUSH	HL
PUSH	AF
LD	E,A
CP	$1B
JR	C,sCTRL
.print1
LD	HL,(sXYADR)
LD	H,0
LD	A,L
SUB	80
JR	C,.pr1
LD	L,0
.pr1
INC	L
LD	(sXYADR),HL
DEC	L
LD	BC,sPRBF
ADD	HL,BC
LD	(HL),E
sPRINT2:
LD	C,$06		;INPOUT
CALL	sSYSTEM
sPRINT3:
POP	AF
POP	HL
POP	DE
POP	BC
AND	A
RET

sPCLR:
XOR	A
LD	(sXYADR),A
RET

sCTRL:
CP	$0D
JR	Z,.CTRL_M
CP	7
JR	Z,sPRINT2
CP	$0C
JR	Z,.CTRL_L
CP	$1A
JR	Z,.CTRL_Z
CP	$0B
JR	Z,.CTRL_K
CP	9
JR	Z,.CTRL_I
JR	sPRINT3
.CTRL_M
CALL	sPCLR
LD	C,$06		;INPOUT
CALL	sSYSTEM
LD	E,$0A		;CRLF
JR	sPRINT2
.CTRL_L
CALL	sPCLR
CALL	sZPRINT
.CTLX1
DB	$1B,"E",0
JR	sPRINT3
.CTRL_Z
CALL	sZPRINT
.CTZX1
DB	$1B,"J",0
JR	sPRINT3
.CTRL_K
CALL	sPCLR
CALL	sZPRINT
.CTKX1
DB	$1B,"H",0
JR	sPRINT3
.CTRL_I
LD	A,(sXYADR)
AND	7
LD	B,A
LD	A,8
SUB	B
LD	B,A
.CTRL_I1
LD	A,$20
CALL	sPRINT
DJNZ	.CTRL_I1
JR	sPRINT3

sWORK:

VSYNC_CHECK:
LD A,1AH
IN A,(01H)
LD HL,LASTVSYNCFLAG
XOR (HL)
RET P
XOR (HL)
LD (HL),A
RET M
; LD HL,VSYNCCOUNTER
INC HL
INC (HL)
JP VSYNC_PROC

VSYNC:
; HL = WAIT COUNT
VSYNC_LOOP:
LD A,(VSYNCCOUNTER)
CP L
JP NC,VSYNC_OVER
PUSH HL
CALL VSYNC_CHECK
POP HL
JP VSYNC_LOOP
VSYNC_OVER:
XOR A
LD (VSYNCCOUNTER),A
RET


